test_that("geographic CRS is rejected", { r<-terra::rast(nrows=2,ncols=2); expect_error(validate_template_crs(r,list()),"projected") })
test_that("current replacement is kilometer Albers", { path<-package_file("spatial_domain","study_area_raster.tif"); skip_if_not(file.exists(path)); r<-terra::rast(path); e<-list(projection="aea",latitude_of_origin=20,central_meridian=-75,latitude_of_first_standard_parallel=10,latitude_of_second_standard_parallel=30,false_easting=0,false_northing=0,datum="WGS84",units="km"); expect_silent(validate_template_crs(r,e)); expect_equal(terra::nrow(r),202); expect_equal(terra::ncol(r),293); expect_equal(terra::res(r)[1],24.99502,tolerance=.001) })
test_that("template fingerprint is stable", { path<-package_file("spatial_domain","study_area_raster.tif"); skip_if_not(file.exists(path)); f<-template_fingerprint(path); expect_equal(f,template_fingerprint(path)); expect_equal(f$non_na_count,16759); expect_equal(toupper(f$sha256),"4BE01F0ECAFF35216A72EB8F27E791311AF90D35B5A4FFF1E46A74EDB6DC633B") })
